  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"cockroachdb\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum MemoryKind {\n  ARCHITECTURE // how the system is structured\n  DECISION // a choice that was made\n  BUG // a known issue\n  TODO // unfinished work\n  WARNING // don't touch / tread carefully\n  IMPORTANT_FILE // a file that matters disproportionately\n  DEPENDENCY // key external dep or integration\n  SECURITY // security consideration\n  CONTEXT // general background context\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// ORGANIZATIONAL MEMORY — knowledge shared across repositories\n// ─────────────────────────────────────────────────────────────────────────────\n\nmodel Organization {\n  id        String   @id @default(cuid())\n  name      String   @unique\n  slug      String   @unique\n  // Engineering standards / conventions all agents in this org must follow\n  standards String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  repos Repository[]\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// REPOSITORY MEMORY — what an agent needs to know about a specific repo\n// ─────────────────────────────────────────────────────────────────────────────\n\nmodel Repository {\n  id        String        @id @default(cuid())\n  // Canonical identifier: absolute path or \"github.com/org/repo\"\n  path      String        @unique\n  name      String\n  orgId     String?\n  org       Organization? @relation(fields: [orgId], references: [id])\n  createdAt DateTime      @default(now())\n  updatedAt DateTime      @updatedAt\n\n  context   RepositoryContext?\n  sessions  CodingSession[]\n  memories  Memory[]\n  decisions Decision[]\n}\n\nmodel RepositoryContext {\n  id     String     @id @default(cuid())\n  repoId String     @unique\n  repo   Repository @relation(fields: [repoId], references: [id], onDelete: Cascade)\n\n  techStack      String[] @default([])\n  importantFiles String[] @default([])\n  architecture   String? // markdown: how the system is structured\n  constraints    String? // hard rules / \"don't touch\" notes\n\n  // Cached count of unresolved TODO + BUG memories — avoids a full scan on load\n  openTaskCount Int @default(0)\n\n  // Deterministic summary built from the structured fields above.\n  // Written as a stable string so re-embedding produces an identical vector.\n  // Never LLM-generated — that would make semantic neighbourhoods drift.\n  contextText      String?\n  // Written via $executeRaw with ::vector cast (Prisma has no native vector type)\n  contextEmbedding Unsupported(\"VECTOR(1024)\")?\n  embeddedAt       DateTime?\n\n  sessionCount  Int       @default(0)\n  lastSessionAt DateTime?\n  updatedAt     DateTime  @updatedAt\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// SESSION MEMORY — what happened during one coding session\n// ─────────────────────────────────────────────────────────────────────────────\n\nmodel CodingSession {\n  id          String     @id @default(cuid())\n  repoId      String\n  repo        Repository @relation(fields: [repoId], references: [id])\n  // \"claude-code\" | \"codex\" | \"cursor\" | \"gemini-cli\" | etc.\n  agentId     String\n  startedAt   DateTime   @default(now())\n  endedAt     DateTime?\n  durationMs  Int?\n  summary     String? // short human-readable summary of what happened\n  // Full structured handoff (WHAT I DID / WHAT FAILED / NEXT) written by\n  // atlas_create_handoff and projected to .atlas/sessions/<date>.md\n  handoffText String?\n  completed   Boolean    @default(false)\n\n  memories  Memory[]\n  decisions Decision[]\n\n  @@index([repoId, startedAt])\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// MEMORY UNITS — individual facts an agent learned or noted\n// ─────────────────────────────────────────────────────────────────────────────\n\nmodel Memory {\n  id        String        @id @default(cuid())\n  sessionId String\n  session   CodingSession @relation(fields: [sessionId], references: [id])\n  repoId    String\n  repo      Repository    @relation(fields: [repoId], references: [id])\n\n  kind       MemoryKind\n  content    String // the fact / note\n  // 1 = low-signal, 5 = critical. Embedding gate: importance >= 3.\n  importance Int        @default(1)\n  tags       String[]   @default([])\n  // TODOs and BUGs can be marked resolved without deletion, preserving history.\n  resolved   Boolean    @default(false)\n\n  // Written via $executeRaw with ::vector cast\n  embedding  Unsupported(\"VECTOR(1024)\")?\n  embeddedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([repoId, kind])\n  @@index([repoId, resolved])\n}\n\nmodel Decision {\n  id        String        @id @default(cuid())\n  sessionId String\n  session   CodingSession @relation(fields: [sessionId], references: [id])\n  repoId    String\n  repo      Repository    @relation(fields: [repoId], references: [id])\n\n  title        String // short label: \"Use Fastify over Express\"\n  rationale    String // why this choice was made\n  alternatives String[] @default([]) // what else was considered\n\n  createdAt DateTime @default(now())\n\n  @@index([repoId])\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// AUDIT — log of every memory retrieval for observability / debugging\n// ─────────────────────────────────────────────────────────────────────────────\n\nmodel MemoryRetrieval {\n  id        String   @id @default(cuid())\n  // \"knn\" | \"tasks\" | \"sessions\" | \"context\" | \"decisions\" | \"search\"\n  kind      String\n  queryText String\n  repoId    String?\n  hitIds    String[]\n  scores    Float[]\n  latencyMs Int\n  createdAt DateTime @default(now())\n\n  @@index([repoId, createdAt])\n}\n",
